        continue
    for f in glob.glob(os.path.join(judge_path, '*.jsonl')):
        with open(f) as fh:
            for line in fh:
                try:
                    d = json.loads(line)
                    for key in ['model_a', 'model_b', 'model', 'target_model', 'target']:
